using OrderId = int;

struct Order {
    OrderId id;
    int quantity;
};

std::optional<Order> find_order(const std::vector<Order>& orders,
                                OrderId wanted) {
    for (const Order& order : orders) {
        if (order.id == wanted) {
            return order;
        }
    }
    return std::nullopt;
}

int open_quantity(const std::vector<Order>& orders, OrderId id) {
    if (auto order = find_order(orders, id)) {
        return order->quantity;  // engagement proved by the condition
    }
    return 0;
}

#include <charconv>
#include <cstdint>
#include <expected>
#include <string_view>

struct Price {
    std::int64_t ticks;
};

enum class PriceError {
    invalid_number,
    trailing_characters,
    negative,
    off_tick
};

std::expected<std::int64_t, PriceError> parse_ticks(std::string_view text) {
    std::int64_t ticks = 0;
    const char* end = text.data() + text.size();
    auto [next, error] = std::from_chars(text.data(), end, ticks);

    if (error != std::errc{}) {
        return std::unexpected(PriceError::invalid_number);
    }
    if (next != end) {
        return std::unexpected(PriceError::trailing_characters);
    }
    return ticks;
}

std::expected<Price, PriceError> validate_price(std::int64_t ticks) {
    if (ticks < 0) {
        return std::unexpected(PriceError::negative);
    }
    if (ticks % 5 != 0) {
        return std::unexpected(PriceError::off_tick);
    }
    return Price{ticks};
}

std::expected<Price, PriceError> decode_price(std::string_view field) {
    return parse_ticks(field).and_then(validate_price);
}

#include <variant>

struct Trade {
    int price;
    int quantity;
};

struct Quote {
    int bid;
    int ask;
};

struct Heartbeat {
    long sequence;
};

using Message = std::variant<Trade, Quote, Heartbeat>;

template<class... Callables>
struct Overloaded : Callables... {
    using Callables::operator()...;
};

long notional(const Message& message) {
    return std::visit(
        Overloaded{
            [](const Trade& trade) -> long {
                return static_cast<long>(trade.price) * trade.quantity;
            },
            [](const Quote& quote) -> long {
                return quote.ask - quote.bid;
            },
            [](const Heartbeat&) -> long { return 0; }
        },
        message);
}

