using Config = std::unordered_map<std::string, std::any>;

template<class T>
T get_or(const Config& config, std::string_view key, T fallback) {
    auto entry = config.find(std::string{key});
    if (entry == config.end()) {
        return fallback;
    }

    // any_cast matches the stored type exactly: an int stored under this key
    // will not satisfy a request for long.
    if (const T* stored = std::any_cast<T>(&entry->second)) {
        return *stored;
    }
    return fallback;
}

#include <bit>
#include <cstdint>
#include <optional>

constexpr int level_count = 64;

std::uint64_t occupy(std::uint64_t mask, int level) {
    if (level < 0 || level >= level_count) {
        return mask;  // shifting by >= the width is undefined behaviour
    }
    return mask | (std::uint64_t{1} << level);
}

std::uint64_t vacate(std::uint64_t mask, int level) {
    if (level < 0 || level >= level_count) {
        return mask;
    }
    return mask & ~(std::uint64_t{1} << level);
}

std::optional<int> best_level(std::uint64_t mask) {
    if (mask == 0) {
        return std::nullopt;  // countr_zero would return 64
    }
    return std::countr_zero(mask);
}

#include <cstdint>
#include <random>

class PriceSimulator {
public:
    explicit PriceSimulator(std::uint64_t seed)
        : seed_(seed), engine_(seed) {}

    double next(double base) {
        return base + jitter_(engine_);
    }

    std::uint64_t seed() const noexcept { return seed_; }

private:
    std::uint64_t seed_;
    std::mt19937_64 engine_;
    std::uniform_real_distribution<double> jitter_{-0.01, 0.01};
};

#include <chrono>

void record_latency(std::chrono::nanoseconds elapsed);

class LatencyTimer {
public:
    // steady_clock never moves backward, so an NTP step or an operator
    // changing the wall clock cannot distort or negate the interval.
    LatencyTimer() : start_(std::chrono::steady_clock::now()) {}

    ~LatencyTimer() {
        auto finish = std::chrono::steady_clock::now();
        record_latency(
            std::chrono::duration_cast<std::chrono::nanoseconds>(
                finish - start_));
    }

    LatencyTimer(const LatencyTimer&) = delete;
    LatencyTimer& operator=(const LatencyTimer&) = delete;

private:
    std::chrono::steady_clock::time_point start_;
};

#include <chrono>

bool is_weekend(std::chrono::year_month_day date) {
    std::chrono::weekday day{std::chrono::sys_days{date}};
    return day == std::chrono::Saturday || day == std::chrono::Sunday;
}

std::chrono::year_month_day month_end(std::chrono::year year,
                                      std::chrono::month month) {
    std::chrono::year_month_day_last last{year / month / std::chrono::last};
    return std::chrono::year_month_day{last};
}
